parameters.jsCode:
const response = $input.first().json;
const raw = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

let parsed;
try {
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { summary: { period: 'Unknown' }, transactions: [], parseError: raw.substring(0, 200) };
}

const s = parsed.summary || {};
const txns = Array.isArray(parsed.transactions) ? parsed.transactions : [];

const fmt = (n) => '₹' + (Number(n) || 0).toLocaleString('en-IN', {minimumFractionDigits: 2});

const topDebits = txns
  .filter(t => t.type === 'debit')
  .sort((a, b) => (Number(b.amount) || 0) - (Number(a.amount) || 0))
  .slice(0, 5)
  .map(t => `• ${(t.description || '').substring(0, 35).padEnd(35)} ${fmt(t.amount)}`);

const msg = [
  '📊 *Bank Statement Processed*',
  `Period: ${s.period || 'N/A'}`,
  '',
  `Opening: ${fmt(s.opening_balance)}`,
  `Credits:  ${fmt(s.total_credits)}`,
  `Debits:   ${fmt(s.total_debits)}`,
  `Closing:  ${fmt(s.closing_balance)}`,
  `Transactions: ${txns.length}`,
  '',
  'Top debits:',
  ...(topDebits.length ? topDebits : ['  No debits found']),
  '',
  `_CSV saved. Import into ActualBudget at https://budget.${process.env.DOMAIN || 'your-domain.com'}_`
].join('\n');

const csvRows = txns.map(t =>
  `"${t.date || ''}","${(t.description || '').replace(/"/g, '""')}","${t.type || ''}",${Number(t.amount) || 0},${Number(t.balance) || 0}`
);
const csv = ['Date,Description,Type,Amount,Balance', ...csvRows].join('\n');

return [{ json: { message: msg, csv, period: s.period || 'unknown', transaction_count: txns.length } }];

const item = $input.first().json;
const fs = require('fs');

const dir = '/home/node/.n8n/bank-statements';
const safePeriod = (item.period || 'unknown').replace(/[^a-zA-Z0-9-]/g, '-');
const filename = `bank-${safePeriod}.csv`;

try {
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(`${dir}/${filename}`, item.csv);
  return [{ json: { ...item, savedPath: `${dir}/${filename}` } }];
} catch(e) {
  return [{ json: { ...item, savedPath: 'save-error: ' + e.message } }];
}
